#include "PedalLookAndFeel.h"
#include <cmath>
namespace adlib93 {
PedalLookAndFeel::PedalLookAndFeel(){setColour(juce::ResizableWindow::backgroundColourId,juce::Colour(0xff191d20));setColour(juce::Slider::textBoxTextColourId,juce::Colour(0xffeee9d9));setColour(juce::Slider::textBoxBackgroundColourId,juce::Colour(0xff101518));setColour(juce::Slider::textBoxOutlineColourId,juce::Colour(0xff495257));setColour(juce::ComboBox::backgroundColourId,juce::Colour(0xff111b1b));setColour(juce::ComboBox::textColourId,juce::Colour(0xffefc179));setColour(juce::TextEditor::backgroundColourId,juce::Colour(0xff111719));setColour(juce::TextEditor::textColourId,juce::Colour(0xffeee9d9));setColour(juce::ToggleButton::textColourId,juce::Colour(0xffeee9d9));setColour(juce::ToggleButton::tickColourId,juce::Colour(0xff69d8d3));}
void PedalLookAndFeel::drawRotarySlider(juce::Graphics& g,int x,int y,int w,int h,float pos,float start,float end,juce::Slider& s){auto r=juce::Rectangle<float>(float(x),float(y),float(w),float(h)).reduced(9);float d=juce::jmin(r.getWidth(),r.getHeight());r=r.withSizeKeepingCentre(d,d);auto c=r.getCentre();g.setColour(juce::Colour(0xff080c0e));g.fillEllipse(r.translated(0,4));g.setGradientFill(juce::ColourGradient(juce::Colour(0xff495256),r.getTopLeft(),juce::Colour(0xff171e21),r.getBottomRight(),false));g.fillEllipse(r);g.setColour(juce::Colour(0xff101719));for(int i=0;i<28;++i){float a=float(i)*juce::MathConstants<float>::twoPi/28;g.drawLine(c.x+std::sin(a)*d*.36f,c.y-std::cos(a)*d*.36f,c.x+std::sin(a)*d*.46f,c.y-std::cos(a)*d*.46f,2);}juce::Path arc;arc.addCentredArc(c.x,c.y,d*.49f,d*.49f,0,start,start+pos*(end-start),true);g.setColour(s.isEnabled()?juce::Colour(0xff69d8d3):juce::Colour(0xff626e6e));g.strokePath(arc,juce::PathStrokeType(2));float a=start+pos*(end-start);g.drawLine(c.x+std::sin(a)*d*.16f,c.y-std::cos(a)*d*.16f,c.x+std::sin(a)*d*.37f,c.y-std::cos(a)*d*.37f,3);if(s.hasKeyboardFocus(true)){g.setColour(juce::Colour(0xffefc179));g.drawRoundedRectangle(juce::Rectangle<float>(float(x)+1,float(y)+1,float(w)-2,float(h)-2),5,2);}}
void PedalLookAndFeel::drawButtonBackground(juce::Graphics& g,juce::Button& b,const juce::Colour&,bool over,bool down){auto r=b.getLocalBounds().toFloat().reduced(1);g.setColour(b.getToggleState()?juce::Colour(0xff26605e):juce::Colour(down?0xff303f42:over?0xff354044:0xff262f33));g.fillRoundedRectangle(r,5);g.setColour(b.getToggleState()?juce::Colour(0xff69d8d3):juce::Colour(0xff596365));g.drawRoundedRectangle(r,5,1);if(b.hasKeyboardFocus(true)){g.setColour(juce::Colour(0xffefc179));g.drawRoundedRectangle(r.reduced(2),4,2);}}
}
